import java.util.*;

class Solution {
  public int maximumNumberOfStringPairs(String[] words) {
    Set<String> seen = new HashSet<>();
    int ans = 0;
    for (String word : words) {
      String reverse = new StringBuilder(word).reverse().toString();
      if (seen.contains(reverse)) ans++;
      seen.add(word);
    }
    return ans;
  }
}
